#include "lsw/agent/system/info.hpp"

#include "lsw/agent/log.hpp"

// Regenerated by CMake (target lsw_agent_stamp) on EVERY build, so
// agent_version always changes — redeploy_agent's "did the swap take"
// poll depends on it. __DATE__/__TIME__ alone was unreliable: this TU
// only recompiles when it (or its deps) change, so a rebuilt agent
// kept reporting a stale version and redeploy always "timed out".
#include "lsw_build_stamp.h"

// clang-format off
// Header order matters: <winsock2.h> MUST be included before <windows.h>
// or the old WinSock 1 declarations leak in and clash with WinSock 2.
// <ws2tcpip.h> brings in inet_ntop / sockaddr_in.
#include <winsock2.h>
#include <ws2tcpip.h>
#include <iphlpapi.h>
#include <windows.h>
#include <sysinfoapi.h>
// clang-format on

#include <atomic>
#include <cstdint>

#include <nlohmann/json.hpp>

namespace lsw::agent::system {

namespace {

// CPU% is computed from the delta of system idle/kernel/user times
// between successive ``system_info`` calls. The first call has no
// prior baseline, so we report 0 until the second call lands.
//
// Stored as a packed 128-bit "snapshot" inside two atomics so the
// stats-poll path can update without taking a mutex. ``valid`` tells
// the next call whether the previous sample is usable.
std::atomic<bool>          g_cpu_baseline_valid{false};
std::atomic<std::uint64_t> g_cpu_last_idle_100ns{0};
std::atomic<std::uint64_t> g_cpu_last_kernel_100ns{0};
std::atomic<std::uint64_t> g_cpu_last_user_100ns{0};

// FILETIME is a 64-bit count of 100-nanosecond intervals. Combine
// the dwLowDateTime / dwHighDateTime halves into one ``uint64``.
[[nodiscard]] std::uint64_t filetime_to_u64(const FILETIME& ft) {
    return (static_cast<std::uint64_t>(ft.dwHighDateTime) << 32)
         |  static_cast<std::uint64_t>(ft.dwLowDateTime);
}

// Sample GetSystemTimes; compute CPU% relative to the prior sample.
// Returns an int in [0, 100]. First call returns 0 (no baseline).
[[nodiscard]] int sample_cpu_percent() {
    FILETIME idle{};
    FILETIME kernel{};
    FILETIME user{};
    if (::GetSystemTimes(&idle, &kernel, &user) == 0) {
        return 0;
    }
    const auto idle_now = filetime_to_u64(idle);
    const auto kernel_now = filetime_to_u64(kernel);
    const auto user_now = filetime_to_u64(user);

    int pct = 0;
    if (g_cpu_baseline_valid.load(std::memory_order_acquire)) {
        const auto idle_prev = g_cpu_last_idle_100ns.load(std::memory_order_relaxed);
        const auto kernel_prev = g_cpu_last_kernel_100ns.load(std::memory_order_relaxed);
        const auto user_prev = g_cpu_last_user_100ns.load(std::memory_order_relaxed);
        // GetSystemTimes(kernel) INCLUDES idle time — busy = (kernel
        // + user) - idle, total = kernel + user. Divide busy/total
        // for the fraction of CPU spent doing work, summed across
        // all logical processors.
        const std::uint64_t total = (kernel_now + user_now) - (kernel_prev + user_prev);
        const std::uint64_t idle_delta = idle_now - idle_prev;
        if (total > 0 && total >= idle_delta) {
            const std::uint64_t busy = total - idle_delta;
            pct = static_cast<int>((busy * 100ULL) / total);
            if (pct > 100) pct = 100;
            if (pct < 0)   pct = 0;
        }
    }
    g_cpu_last_idle_100ns.store(idle_now, std::memory_order_relaxed);
    g_cpu_last_kernel_100ns.store(kernel_now, std::memory_order_relaxed);
    g_cpu_last_user_100ns.store(user_now, std::memory_order_relaxed);
    g_cpu_baseline_valid.store(true, std::memory_order_release);
    return pct;
}

std::string get_hostname() {
    char buf[256] = {};
    DWORD n = sizeof(buf);
    ::GetComputerNameA(buf, &n);
    return std::string{buf, n};
}

std::string get_primary_ipv4() {
    ULONG sz = 16384;
    auto* addrs = static_cast<IP_ADAPTER_ADDRESSES*>(::HeapAlloc(::GetProcessHeap(), 0, sz));
    if (addrs == nullptr) {
        return {};
    }
    if (::GetAdaptersAddresses(AF_INET, GAA_FLAG_SKIP_ANYCAST | GAA_FLAG_SKIP_MULTICAST, nullptr,
                               addrs, &sz) != NO_ERROR) {
        ::HeapFree(::GetProcessHeap(), 0, addrs);
        return {};
    }
    std::string out;
    for (auto* a = addrs; a != nullptr; a = a->Next) {
        if (a->OperStatus != IfOperStatusUp)
            continue;
        for (auto* u = a->FirstUnicastAddress; u != nullptr; u = u->Next) {
            char buf[64] = {};
            sockaddr_in* sa = reinterpret_cast<sockaddr_in*>(u->Address.lpSockaddr);
            ::inet_ntop(AF_INET, &sa->sin_addr, buf, sizeof(buf));
            out = buf;
            break;
        }
        if (!out.empty())
            break;
    }
    ::HeapFree(::GetProcessHeap(), 0, addrs);
    return out;
}

}  // namespace

std::string Info::collect_json() {
    LSW_AGENT_DEBUG("system_info: collecting");
    MEMORYSTATUSEX ms{};
    ms.dwLength = sizeof(ms);
    ::GlobalMemoryStatusEx(&ms);
    OSVERSIONINFOA osv{};
    osv.dwOSVersionInfoSize = sizeof(osv);
#pragma warning(suppress : 4996)
    ::GetVersionExA(&osv);

    // System drive (C:\ in a stock install). GetDiskFreeSpaceExW
    // returns the per-user / total bytes; we want the volume-wide
    // total/free, so pass nullptr for the per-user out.
    ULARGE_INTEGER disk_free{};
    ULARGE_INTEGER disk_total{};
    if (::GetDiskFreeSpaceExW(L"C:\\", nullptr, &disk_total, &disk_free) == 0) {
        disk_free.QuadPart = 0;
        disk_total.QuadPart = 0;
    }

    const int cpu_pct = sample_cpu_percent();

    nlohmann::json j = nlohmann::json::object();
    j["os"] = "Windows " + std::to_string(osv.dwMajorVersion) + "." +
              std::to_string(osv.dwMinorVersion) + "." + std::to_string(osv.dwBuildNumber);
    const auto hostname = get_hostname();
    const auto ipv4 = get_primary_ipv4();
    j["hostname"] = hostname;
    j["ipv4"] = ipv4;
    j["mem_total"] = static_cast<std::uint64_t>(ms.ullTotalPhys);
    j["mem_avail"] = static_cast<std::uint64_t>(ms.ullAvailPhys);
    j["cpu_percent"] = cpu_pct;
    j["disk_total"] = static_cast<std::uint64_t>(disk_total.QuadPart);
    j["disk_avail"] = static_cast<std::uint64_t>(disk_free.QuadPart);
    // Build marker — unique per compile of this translation unit.
    // ``redeploy_agent`` (manager MCP tool / scripts/redeploy-agent.sh)
    // reads this to verify a hot-swap took effect: the value must
    // differ from what the previous agent reported before the script
    // killed it.
    j["agent_version"] = LSW_BUILD_STAMP;
    LSW_AGENT_INFO(std::string{"system_info: hostname="} + hostname + " ipv4=" + ipv4
                   + " mem_total=" + std::to_string(ms.ullTotalPhys >> 20) + "MiB"
                   + " mem_avail=" + std::to_string(ms.ullAvailPhys >> 20) + "MiB"
                   + " cpu=" + std::to_string(cpu_pct) + "%"
                   + " disk_total=" + std::to_string(disk_total.QuadPart >> 30) + "GiB"
                   + " disk_avail=" + std::to_string(disk_free.QuadPart >> 30) + "GiB");
    return j.dump();
}

}  // namespace lsw::agent::system
